&lt;/a&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Conjurateur.html&quot; title=&quot;Le conjurateur (aussi appel&#233; invocateur)&quot;&gt;Conjurateur&lt;/a&gt;.&lt;/b&gt; Le conjurateur rajoute +1 &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;point de vie&lt;/a&gt; ou +1 &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html#ACQUERIR&quot; title=&quot;Les comp&#233;tences&quot;&gt;rang de comp&#233;tence&lt;/a&gt; &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Conjurateur.html#EIDOLON&quot; title=&quot;Le conjurateur (aussi appel&#233; invocateur)&quot;&gt;eidolon&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
